+        navigate(ContactView.class);
+        $(com.vaadin.flow.component.textfield.TextField.class).withCaption("Name").single().setValue("a");
+        $(com.vaadin.flow.component.textfield.TextField.class).withCaption("Phone").single().setValue("1");
+        $(com.vaadin.flow.component.textfield.TextArea.class).single().setValue("hi");
